// Replays fixtures produced by the Python modules and checks the JavaScript port gives identical results.
// The fixture is generated by tests/test_js_engine.py (env PARITY_FIXTURE); without it these tests are skipped.
const test = require("node:test");
const assert = require("node:assert/strict");
const fs = require("node:fs");
const E = require("../../dashboard/assets/engine.js");

const path = process.env.PARITY_FIXTURE;
const fx = path ? JSON.parse(fs.readFileSync(path, "utf8")) : null;
const opts = { skip: fx ? false : "PARITY_FIXTURE not set (run via pytest tests/test_js_engine.py)" };

test("finger detection matches vision_processor.py on random landmark sets", opts, () => {
  assert.ok(fx.landmarks.length >= 300);
  fx.landmarks.forEach((c, i) => {
    assert.deepEqual(E.fingerStates5(c.lm), c.fingers, `case ${i}`);
    assert.ok(Math.abs(E.thumbRatio(c.lm) - c.thumb_ratio) < 1e-9, `thumb ratio ${i}`);
  });
});

test("GestureLogic + ModeSwitch match pipeline.py / instrument_modes.py step by step", opts, () => {
  let steps = 0, switches = 0, noteOns = 0;
  fx.sequences.forEach((seq, si) => {
    const logic = new E.GestureLogic(seq.debounce_ms, seq.lost_grace_ms);
    const sw = new E.ModeSwitch(seq.hold_s, seq.dropout_s);
    seq.steps.forEach((st, k) => {
      const hands = st.hands.map(([side, fingers]) => ({ side, fingers }));
      const by = {}; hands.forEach((h) => { by[h.side] = h; });
      const switched = sw.update(by.left ? by.left.fingers : null, by.right ? by.right.fingers : null, st.t);
      const out = logic.update(hands, st.t);
      const where = `seq ${si} step ${k}`;
      const cmds = out.commands.map((c) => (c.type === "note_on" ? ["note_on", c.midi] : ["note_off"]));
      assert.deepEqual(cmds, st.commands, where + " commands");
      assert.deepEqual(out.events, st.events, where + " events");
      assert.equal(logic.current ? logic.current.label : null, st.current, where + " current");
      assert.equal(logic.minorActive, st.minor, where + " minor");
      assert.equal(switched, st.switched, where + " switched");
      assert.ok(Math.abs(sw.progress - st.progress) < 1e-9, where + " progress");
      steps++; switches += switched ? 1 : 0; noteOns += st.events.filter((e) => e.kind === "note_on").length;
    });
  });
  // the fixture must be rich enough to be meaningful
  assert.ok(steps > 3000 && switches > 0 && noteOns > 100, `steps=${steps} switches=${switches} noteOns=${noteOns}`);
});

test("solfege / minor resolution matches gesture_matrix.resolve_pair for every pattern pair", opts, () => {
  fx.pairs.forEach((p, i) => {
    const n = E.resolvePair(p.melody, p.modifier);
    assert.deepEqual(n ? [n.solfege, n.midi, n.minor, n.name, n.label] : null, p.note, `pair ${i}`);
  });
  assert.equal(fx.pairs.length, 32 * 32 + 64);
});

test("configure() follows the payload shape of GET /api/config", opts, () => {
  E.configure(fx.api_config);
  assert.equal(E.settings.minorShift, fx.api_config.minor_shift);
  assert.equal(E.settings.holdS, fx.api_config.mode_switch_hold_s);
  assert.equal(Object.keys(E.settings.solfege).length, fx.api_config.solfege.length);
  assert.equal(E.settings.openRatio, fx.api_config.vision.open_ratio);
  assert.equal(E.settings.solfege["10000"][0], "C");
});